import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.DHSXpJLs.js";const u=JSON.parse('{"title":"故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1790779354000}'),a={name:"guide/troubleshooting.md"};function c(n,t,i,l,s,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><p>按现象查表。多数问题的根因集中在三类：<strong>数据目录不一致</strong>、<strong>沙箱不可用</strong>、<strong>LLM key 没配</strong>。机制说明见对应页面，本页只讲怎么办。</p><h2 id="模型与查看" tabindex="-1">模型与查看 <a class="header-anchor" href="#模型与查看" aria-label="Permalink to &quot;模型与查看&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>模型一直停在 <code>converting</code></td><td>看 server 日志里的 converter stderr；手动复现：<code>node converter/convert.js &lt;input.ifc&gt; &lt;outDir&gt;</code>；核对 <code>nodeBin</code> 与 <code>converterScript</code> 配置</td></tr><tr><td>模型 <code>failed</code></td><td>调 <code>POST /api/v1/models/{id}/retry</code> 重新入队转换</td></tr><tr><td>编辑请求报 404 model not found</td><td>编辑服务的 <code>VIEWER_DATA_DIR</code> 与 server 的 <code>dataDir</code> 不是同一个目录——两边必须指向同一个 <code>data</code> 绝对路径</td></tr><tr><td>页面报 401</td><td>没带 token。浏览器把 token 存在 localStorage 的 <code>aiifc_token</code> 键，弹框保存后会自动重试原请求</td></tr><tr><td>打开 :8090 静态路径 503，API 却正常</td><td><code>webDist</code> 指的前端构建产物目录不存在，先 <code>cd web &amp;&amp; npm run build</code></td></tr></tbody></table><h2 id="编辑与版本" tabindex="-1">编辑与版本 <a class="header-anchor" href="#编辑与版本" aria-label="Permalink to &quot;编辑与版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>脚本编辑报 422</td><td>契约静态校验、沙箱构建或依赖解析失败。请求零副作用，按报错信息修正后重发</td></tr><tr><td>脚本编辑报 429</td><td>并发闸满（<code>SCRIPT_RUN_CONCURRENCY</code>），稍后重试</td></tr><tr><td>脚本编辑报 503</td><td>沙箱不可用：缺 <code>bwrap</code> 或缺 <code>uv</code>，属部署问题，不降级执行</td></tr><tr><td>edit-call 报 409</td><td>暂存脚本与 ScriptMap 分叉——暂存了新脚本但没运行过。先跑一次试运行再定位或改写</td></tr><tr><td>定位脚本返回 <code>found: false</code></td><td>该构件不在当前 ScriptMap 里，这是正常响应不是错误。模型可能是 plain 态（没有构建脚本），先让 AI 复现成脚本</td></tr><tr><td>改了脚本前端没刷新</td><td>直连编辑服务的 run/save <strong>不触发</strong> XKT 重转（<code>retry</code> 只对 <code>failed</code> 模型有效，帮不上忙）。改走 Go 代理（:8090）的 <code>script/run</code>、<code>script/save</code>、<code>script/rollback</code></td></tr></tbody></table><h2 id="ai-与存储" tabindex="-1">AI 与存储 <a class="header-anchor" href="#ai-与存储" aria-label="Permalink to &quot;AI 与存储&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>AI 对话没有智能回复</td><td>LLM 三参没配，正处于离线模式。配置 <code>VIEWER_LLM_API_KEY</code>、<code>VIEWER_LLM_BASE_URL</code>、<code>VIEWER_LLM_MODEL</code></td></tr><tr><td>agent 的文件工具报错</td><td>grep 工具依赖 ripgrep，装上即可（Debian/Ubuntu：<code>sudo apt install ripgrep</code>）</td></tr><tr><td>PostgreSQL 连不上</td><td>清空 <code>pgDSN</code>（或 <code>VIEWER_PG_DSN</code>）回退文件存储，或核对 DSN</td></tr></tbody></table><h2 id="状态码去哪查" tabindex="-1">状态码去哪查 <a class="header-anchor" href="#状态码去哪查" aria-label="Permalink to &quot;状态码去哪查&quot;">​</a></h2><p>编辑请求的失败语义分散在两处，按归属看：</p><ul><li><strong>422、429、503 属沙箱</strong>——契约或构建失败（零副作用）、并发闸满、沙箱不可用。逐条定义见<a href="/SourceAEC/development/sandbox">沙箱执行环境</a>的失败语义表。</li><li><strong>409 属编辑契约</strong>——暂存脚本与 ScriptMap 分叉，<code>edit-call</code> 拒绝执行。见 <a href="/SourceAEC/reference/edit-api#定位链路">IFC 编辑 API</a>。</li></ul><p>这四种失败都不产生半成品版本，暂存链也不会被写坏。</p><p>验证手段见<a href="/SourceAEC/development/testing">测试与调试</a>：冒烟脚本覆盖上传到编辑的全链路，手工清单覆盖界面。</p>',13)])])}const b=e(a,[["render",c]]);export{u as __pageData,b as default};
